const ComponentTaleClass = require ('../ComponentTale');
const getTaleOriginName = require ('./getTaleOriginName');

class TaleManager {
  constructor({}) {
    this.talesArray = [];
    this.talesObject = {};

    this.getTale = this.getTale.bind (this);
    this.createTale = this.createTale.bind (this);
    this.getSiblingTales = this.getSiblingTales.bind (this);
  }

  getTale (taleIdentifier) {
    const ComponentTale = this.talesObject[taleIdentifier];
    if (!!ComponentTale) return ComponentTale;
    return this.createTale (taleIdentifier);
  }

  createTale (taleIdentifier) {
    const taleOriginName = getTaleOriginName (taleIdentifier);
    const ComponentTale = new ComponentTaleClass ({
      taleName: taleIdentifier,
      taleOriginName,
    });

    this.talesArray.push (ComponentTale);
    this.talesObject[taleIdentifier] = ComponentTale;

    return ComponentTale;
  }

  getSiblingTales (taleIdentifier) {
    const taleOriginName = getTaleOriginName (taleIdentifier);
    const tales = {};
    this.talesArray
      .filter (Tale => Tale.taleOriginName === taleOriginName)
      .forEach (Tale => (tales[Tale.taleName] = Tale));
    return tales;
  }
}

module.exports = new TaleManager ({});
